import os # Use consistent numeric reductions while checking saved full-field evidence.
os.environ['OMP_NUM_THREADS']='1';os.environ['OPENBLAS_NUM_THREADS']='1' # Match the frozen single-thread evaluation environment.
import argparse,json,zipfile # Validate every compressed member and preserve actual file identities.
import numpy as np # Compare complete physical arrays without spatial or temporal sampling.
import complex_operator as base # Reuse canonical repository paths and hashing only.
def run(family): # Verify final complete archives before a family is declared deliverable.
    registry=json.loads((base.ROOT/'learning/campaign_learning_index.json').read_text());directory=base.ROOT/registry['families'][family];index=json.loads((directory/'source_index.json').read_text());rows={row['id']:row for row in index['cases']};records=[];failures=[];files=sorted(list((directory/'final_test').glob('*/*.npz'))+list((directory/'mesh_transfer').glob('*/*.npz')));registered=sum(row['split'] in ['test','ood'] for row in index['cases']);assert len(list((directory/'final_test').glob('*/*.npz')))==3*registered,'Missing final whole-history archives' # Retain the complete three-model held-out denominator.
    for path in files: # Inspect every actual saved final prediction and separate mesh-transfer artifact.
        item={'path':str(path.relative_to(directory)),'size':path.stat().st_size,'sha256':base.digest(path)} # Preserve failure identity even when a ZIP cannot be opened.
        try: # Keep corrupt-deliverable errors distinct from scientific neural accuracy failures.
            with zipfile.ZipFile(path) as archive: assert archive.testzip() is None # Validate every compressed member's CRC rather than only opening the ZIP directory.
            saved=np.load(path,allow_pickle=False);row=rows.get(path.stem) # Resolve the registered complete physical history behind this file.
            if row is None: row=json.loads((base.ROOT/family/'cases'/path.stem/'case.json').read_text()) # Existing friction mesh checks retain their own explicit native-reference row.
            source=base.resolve_path(row['npz']);assert str(saved['npz_sha256'])==base.digest(source),'Native source hash changed';native=np.load(source,allow_pickle=False);reference=np.asarray(native['states'],dtype=np.float64);assert saved['prediction'].shape==saved['reference'].shape==saved['difference'].shape==reference.shape;assert np.array_equal(saved['reference'],reference) and np.array_equal(saved['difference'],saved['prediction']-reference,equal_nan=True),'Saved reference or difference cannot be reproduced';item.update({'shape':list(reference.shape),'native_npz':str(source),'native_sha256':base.digest(source),'zip_crc_verified':True,'reference_and_difference_exactly_reproduced':True,'status':'PASS'}) # Verify the original physical field arrays at every entity and output time.
        except Exception as error: item.update({'status':'ARTIFACT_INTEGRITY_ERROR','error':f'{type(error).__name__}: {error}'});failures.append(item) # Preserve the actual defect and refuse a success marker until it is repaired and rechecked.
        records.append(item) # Include successes and failures in the same complete archive denominator.
    result={'family':family,'archives':records,'count':len(records),'expected_final_test_archives':3*registered,'failures':failures,'all_zip_crc_and_shape_checks_passed':not failures,'all_zip_crc_shape_and_reference_checks_passed':not failures,'repair_receipt':'artifact_integrity_quarantine/fine_mesh_recovery_receipt.json' if (directory/'artifact_integrity_quarantine/fine_mesh_recovery_receipt.json').exists() else None,'scientific_accuracy_gate_unchanged':True};base.write(directory/'final_artifact_integrity.json',result);assert not failures,'Final artifact integrity verification failed';print(json.dumps({'family':family,'archives_verified':len(records),'status':'PASS'}),flush=True) # Successful storage integrity does not override any field, physics or continuum-fidelity HOLD.
if __name__=='__main__': # Run this stage after frozen final prediction export and before packaging.
    parser=argparse.ArgumentParser();parser.add_argument('--family',choices=['friction','rebar','thermoplastic'],required=True);run(parser.parse_args().family) # Require an explicit completed canonical family.
